'use strict';
window.Sound467={enabled:true,volume:.35,muted:false,context:null,seen:new Set(),lastAt:0,ready:false,
 t:(z,e)=>I18n.language==='en'?e:z,
 init(){if(this.ready)return;this.ready=true;this.enabled=true;this.storageKey='musonoi-sound:'+CurrentUser.id+':'+ProductContext.code;try{const saved=JSON.parse(localStorage.getItem(this.storageKey));if(saved){this.enabled=saved.enabled===true;this.volume=Number.isFinite(Number(saved.volume))?Math.max(0,Math.min(1,Number(saved.volume))):.35;}}catch{}this.gestureAbort?.abort();this.gestureAbort=new AbortController();const activate=()=>{if(this.enabled&&!this.muted&&window.AppSignedIn&&!document.hidden)this.unlock().then(()=>this.refresh()).catch(()=>this.refresh());};for(const type of ['pointerdown','keydown'])document.addEventListener(type,activate,{signal:this.gestureAbort.signal,passive:true});this.refresh();},
 save(){try{localStorage.setItem(this.storageKey,JSON.stringify({enabled:this.enabled,volume:this.volume}));}catch{}this.refresh();},
 refresh(){if(!this.ready||!window.AppSignedIn)return;let b=document.getElementById('sound467-open');if(!b){const host=document.querySelector('.top-actions');if(!host)return;b=document.createElement('button');b.type='button';b.id='sound467-open';b.className='button secondary sound467-entry';b.dataset.noI18n='';b.onclick=()=>this.open();host.append(b);}b.textContent=this.t('声音 · ','Sound · ')+(this.enabled&&!this.muted?this.context?.state==='running'?this.t('开','On'):this.t('待激活','Activate'):this.t('关','Off'));b.title=this.t('待办声音设置（本机、当前账号和产品）','Task Sound Settings (this device, account and product)');b.setAttribute('aria-pressed',String(this.enabled&&!this.muted));},
 async unlock(){const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw Error(this.t('当前浏览器不支持提示音。','This browser does not support task sounds.'));this.context||=new Audio();if(this.context.state!=='running')await this.context.resume();if(this.context.state!=='running')throw Error(this.t('浏览器尚未允许播放，请点击试听重试。','The browser has not allowed playback. Click Preview to retry.'));},
 async play(preview=false){if(!preview&&(!this.enabled||this.muted||document.hidden||!window.AppSignedIn||!this.context||this.context.state!=='running'))return false;if(preview)await this.unlock();const ctx=this.context;if(!ctx||ctx.state!=='running')return false;const gain=ctx.createGain(),osc=ctx.createOscillator(),at=ctx.currentTime;osc.type='sine';osc.frequency.setValueAtTime(660,at);osc.frequency.setValueAtTime(880,at+.12);gain.gain.setValueAtTime(0,at);gain.gain.linearRampToValueAtTime(this.volume*.22,at+.02);gain.gain.exponentialRampToValueAtTime(.0001,at+.3);osc.connect(gain);gain.connect(ctx.destination);osc.start(at);osc.stop(at+.32);osc.onended=()=>{osc.disconnect();gain.disconnect();};return true;},
 notify(keys,{initial=false}={}){const fresh=keys.filter(k=>!this.seen.has(k));for(const key of keys)this.seen.add(key);if(this.seen.size>2000)this.seen=new Set([...this.seen].slice(-1000));if(initial||!fresh.length||!this.enabled||this.muted||document.hidden||!this.context||this.context.state!=='running')return;const now=Date.now();if(now-this.lastAt<30000)return;this.lastAt=now;this.play().catch(()=>{});},
 open(){if(document.querySelector('dialog[open]')){notify(this.t('请先关闭当前对话框。','Close the current dialog first.'));return;}const t=this.t,box=document.createElement('dialog');box.id='sound467-dialog';box.className='sound467-dialog';box.dataset.noI18n='';box.setAttribute('aria-labelledby','sound467-title');box.innerHTML='<h2 id="sound467-title">'+t('待办声音设置','Task Sound Settings')+'</h2><p>'+t('仅对本人有权办理的新单据或审批节点提示。同单同节点去重，30秒内合并提示；隐藏页面暂停。浏览器可能要求每次打开后点击启用或试听。','Only new documents or approval stages you can process are eligible. Each document stage is deduplicated; sounds are limited to one per 30 seconds and paused on hidden pages. Your browser may require Enable or Preview after reopening.')+'</p><label class="sound467-toggle"><input id="sound467-enabled" type="checkbox"'+(this.enabled?' checked':'')+'>'+t('启用待办声音（默认开启）','Enable Task Sounds (on by default)')+'</label><label>'+t('音量','Volume')+' <output id="sound467-volume-value">'+Math.round(this.volume*100)+'%</output><input id="sound467-volume" type="range" min="0" max="100" step="5" value="'+Math.round(this.volume*100)+'"></label><label class="sound467-toggle"><input id="sound467-muted" type="checkbox"'+(this.muted?' checked':'')+'>'+t('本次静音','Mute This Session')+'</label><p id="sound467-error" role="alert" class="error"></p><div class="business-toolbar"><button id="sound467-preview" type="button" class="button secondary">'+t('试听一声','Preview Sound')+'</button><button id="sound467-close" type="button" class="button primary">'+t('完成','Done')+'</button></div><small>'+t('设置只保存在本机当前账号及产品；不发送系统通知。','Settings stay on this device for the current account and product. No system notifications are sent.')+'</small>';
  const origin=document.activeElement;document.body.append(box);const error=e=>box.querySelector('#sound467-error').textContent=e.message;box.querySelector('#sound467-enabled').onchange=async e=>{this.enabled=e.target.checked;if(this.enabled)try{await this.unlock();}catch(err){this.enabled=false;e.target.checked=false;error(err);}this.save();};box.querySelector('#sound467-volume').oninput=e=>{this.volume=Number(e.target.value)/100;box.querySelector('#sound467-volume-value').textContent=e.target.value+'%';this.save();};box.querySelector('#sound467-muted').onchange=e=>{this.muted=e.target.checked;this.refresh();};box.querySelector('#sound467-preview').onclick=async()=>{try{await this.play(true);}catch(e){error(e);}};const close=()=>{box.close();box.remove();origin?.isConnected&&origin.focus();};box.querySelector('#sound467-close').onclick=close;box.oncancel=e=>{e.preventDefault();close();};box.showModal();box.querySelector('#sound467-enabled').focus();
 },
 stop(){this.gestureAbort?.abort();this.ready=false;this.enabled=false;this.muted=false;this.seen.clear();this.context?.close().catch(()=>{});this.context=null;document.getElementById('sound467-open')?.remove();document.getElementById('sound467-dialog')?.remove();}
};
